/**
 * ─────────────────────────────────────────────────────────────────
 *  MAZAJ LOGO GEOMETRY — the algorithmic heart of the brand mark
 * ─────────────────────────────────────────────────────────────────
 *  Pure, deterministic geometry shared by:
 *    • src/components/hookah/logo.tsx  (the animated in-app logo)
 *    • scripts/render-logo-icons.ts    (the rasterized PWA icons)
 *
 *  The smoke tendrils are NOT hand-drawn: each is generated by a
 *  seeded PRNG driving a sine-perturbed bezier chain, so the smoke
 *  looks organic yet renders identically on server & client (no
 *  hydration drift) and in the offline icon rasterizer.
 *
 *  Coordinate space: viewBox 0 0 120 132 (hookah below, smoke above).
 * ─────────────────────────────────────────────────────────────────
 */

/** Deterministic PRNG (mulberry32) — same sequence for a given seed. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

