/* ── The smoke — procedurally generated tendrils ──────────────────── */

export interface TendrilSpec {
  seed: number;
  x0: number;
  y0: number;
  rise: number;
  segments: number;
  sway: number;
  width: number;
  opacity: number;
  /** seconds for the upward dash drift loop */
  drift: number;
}

/** The three living smoke curls (fixed seeds → deterministic). */
export const SMOKE_TENDRILS: TendrilSpec[] = [
  { seed: 11, x0: 54.5, y0: 41, rise: 33, segments: 5, sway: 6.5, width: 2.6, opacity: 0.5, drift: 11 },
  { seed: 47, x0: 60.5, y0: 39, rise: 36, segments: 6, sway: 8.0, width: 3.3, opacity: 0.62, drift: 14 },
  { seed: 83, x0: 66, y0: 41, rise: 31, segments: 5, sway: 6.0, width: 2.3, opacity: 0.44, drift: 9 },
];

/**
 * Generate one smoke tendril: a chain of cubic beziers whose horizontal
 * sway follows a sine wave (amplitude grows with height) with a touch of
 * seeded jitter — smoke that feels alive but is fully deterministic.
 */
export function smokePath(spec: TendrilSpec): string {
  const rnd = mulberry32(spec.seed);
  const stepY = spec.rise / spec.segments;
  const phase = rnd() * Math.PI * 2;
  const freq = 1.7 + rnd() * 0.9;
  let x = spec.x0;
  let y = spec.y0;
  let d = `M ${x.toFixed(1)} ${y.toFixed(1)}`;
  for (let i = 0; i < spec.segments; i++) {
    const t = (i + 1) / spec.segments;
    const amp = spec.sway * (0.28 + t * 0.85);
    const dx = Math.sin(phase + t * Math.PI * freq) * amp + (rnd() - 0.5) * 2.4;
    const dy = -stepY * (0.85 + rnd() * 0.3);
    const nx = x + dx;
    const ny = y + dy;
    const cx1 = x + dx * 0.25 + (rnd() - 0.5) * 1.6;
    const cy1 = y + dy * 0.42;
    const cx2 = nx - dx * 0.25 + (rnd() - 0.5) * 1.6;
    const cy2 = ny - dy * 0.35;
    d += ` C ${cx1.toFixed(1)} ${cy1.toFixed(1)} ${cx2.toFixed(1)} ${cy2.toFixed(1)} ${nx.toFixed(1)} ${ny.toFixed(1)}`;
    x = nx;
    y = ny;
  }
  return d;
}

/** All tendril paths, precomputed once (deterministic). */
export const SMOKE_PATHS: string[] = SMOKE_TENDRILS.map(smokePath);

/**
 * A gentle rising trajectory for an ember spark (used with
 * <animateMotion>). Deterministic per seed.
 */
export function emberTrail(seed: number): string {
  const rnd = mulberry32(seed);
  const sway = 3 + rnd() * 4;
  const h = 16 + rnd() * 10;
  const mid = (rnd() - 0.5) * 6;
  return `M 0 0 C ${sway.toFixed(1)} ${(-h * 0.35).toFixed(1)} ${mid.toFixed(1)} ${(-h * 0.7).toFixed(1)} ${(mid + sway * 0.4).toFixed(1)} ${(-h).toFixed(1)}`;
}
